   361  exr_result_t
   362  exr_get_scanlines_per_chunk (
   363      exr_const_context_t ctxt, int part_index, int32_t* out)
   364  {
   365      EXR_PROMOTE_CONST_CONTEXT_AND_PART_OR_ERROR (ctxt, part_index);
   366
   367      if (!out)
   368          return EXR_UNLOCK_WRITE_AND_RETURN_PCTXT (EXR_ERR_INVALID_ARGUMENT);
   369
   370      if (part->storage_mode == EXR_STORAGE_SCANLINE ||
   371          part->storage_mode == EXR_STORAGE_DEEP_SCANLINE)
   372      {
   373          *out = part->lines_per_chunk;
   374          return EXR_UNLOCK_WRITE_AND_RETURN_PCTXT (EXR_ERR_SUCCESS);
   375      }
   376      return EXR_UNLOCK_WRITE_AND_RETURN_PCTXT (
   377          pctxt->standard_error (pctxt, EXR_ERR_SCAN_TILE_MIXEDAPI));
   378  }
