   382  exr_result_t
   383  exr_get_chunk_unpacked_size (
   384      exr_const_context_t ctxt, int part_index, uint64_t* out)
   385  {
   386      uint64_t sz;
   387      EXR_PROMOTE_CONST_CONTEXT_AND_PART_OR_ERROR (ctxt, part_index);
   388      sz = part->unpacked_size_per_chunk;
   389      EXR_UNLOCK_WRITE (pctxt);
   390
   391      if (!out) return pctxt->standard_error (pctxt, EXR_ERR_INVALID_ARGUMENT);
   392
   393      *out = sz;
   394      return EXR_ERR_SUCCESS;
   395  }
